#!/bin/sh
# Writes the Homebrew formula (mymule.rb) and the Scoop manifest
# (mymule.json) for a release, from its SHA256SUMS file.
#
#   render.sh VERSION SHA256SUMS OWNER/REPO OUTDIR
#   render.sh v1.2.3 dist/SHA256SUMS someone/MyMule out
#
# The release workflow pushes them to the OWNER/homebrew-tap and
# OWNER/scoop-bucket repositories.
set -eu

tag=$1 sums=$2 repo=$3 out=$4
version=${tag#v}
base="https://github.com/$repo/releases/download/$tag"

sha() {
	h=$(awk -v f="mymule-$tag-$1" '$2 == f || $2 == "*" f { print $1 }' "$sums")
	[ -n "$h" ] || { echo "no checksum for mymule-$tag-$1 in $sums" >&2; exit 1; }
	echo "$h"
}

mkdir -p "$out"

# Homebrew. The program keeps its data next to the executable, which
# Homebrew replaces on every upgrade: the mymule command is a wrapper that
# sets MYMULE_HOME to ~/MyMule unless it is already set.
cat > "$out/mymule.rb" <<RUBY
# Generated by the MyMule release workflow; changes here are overwritten.
class Mymule < Formula
  desc "Client for the eMule networks (eD2K and Kad) with a web interface"
  homepage "https://github.com/$repo"
  version "$version"
  license "GPL-3.0-or-later"

  on_macos do
    on_arm do
      url "$base/mymule-$tag-darwin-arm64.tar.gz"
      sha256 "$(sha darwin-arm64.tar.gz)"
    end
    on_intel do
      url "$base/mymule-$tag-darwin-amd64.tar.gz"
      sha256 "$(sha darwin-amd64.tar.gz)"
    end
  end

  on_linux do
    on_arm do
      url "$base/mymule-$tag-linux-arm64.tar.gz"
      sha256 "$(sha linux-arm64.tar.gz)"
    end
    on_intel do
      url "$base/mymule-$tag-linux-amd64.tar.gz"
      sha256 "$(sha linux-amd64.tar.gz)"
    end
  end

  def install
    libexec.install "mymule"
    (bin/"mymule").write <<~SH
      #!/bin/sh
      # Settings, downloads and log live in ~/MyMule (or in \$MYMULE_HOME).
      : "\${MYMULE_HOME:=\$HOME/MyMule}"
      export MYMULE_HOME
      exec "#{opt_libexec}/mymule" "\$@"
    SH
  end

  def caveats
    <<~EOS
      Settings, downloads and the log are kept in ~/MyMule
      (set MYMULE_HOME to use another folder).

      Start it in the background and see what it is doing:
        mymule start
        mymule top
      The web interface is off by default: set web_ui = true in
      ~/MyMule/mymule.conf, run 'mymule stop' and 'mymule start',
      and open http://127.0.0.1:4711/
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/mymule version")
  end
end
RUBY

# Scoop. Scoop installs every version in its own folder, so MYMULE_HOME
# points to Scoop's persist folder, which upgrades keep.
cat > "$out/mymule.json" <<JSON
{
    "##": "Generated by the MyMule release workflow; changes here are overwritten.",
    "version": "$version",
    "description": "Client for the eMule networks (eD2K and Kad) with a web interface",
    "homepage": "https://github.com/$repo",
    "license": "GPL-3.0-or-later",
    "architecture": {
        "64bit": {
            "url": "$base/mymule-$tag-windows-amd64.zip",
            "hash": "$(sha windows-amd64.zip)",
            "extract_dir": "mymule-$tag-windows-amd64"
        },
        "arm64": {
            "url": "$base/mymule-$tag-windows-arm64.zip",
            "hash": "$(sha windows-arm64.zip)",
            "extract_dir": "mymule-$tag-windows-arm64"
        }
    },
    "bin": "mymule.exe",
    "env_set": {
        "MYMULE_HOME": "\$persist_dir"
    },
    "notes": [
        "Settings, downloads and the log are kept in \$persist_dir",
        "(set MYMULE_HOME to use another folder, or download_dir in mymule.conf).",
        "Start it with 'mymule start' and watch it with 'mymule top'."
    ]
}
JSON
